	const perksRaw = body.log?.perks;
	if (!Array.isArray(dirsRaw) || !Array.isArray(perksRaw)) throw new HttpError(400, "bad_log");
	if (dirsRaw.length > Math.min(t + 1, 2e4) || perksRaw.length > 2) throw new HttpError(400, "bad_log");
	let prev = -1;
