	if (now - att.startedAt > FINISH_WINDOW_MS) throw new HttpError(410, "attempt_expired");
	const { ticks, log } = parseLog(body);
	if (ticks / TICK_HZ > (now - att.startedAt) / 1e3 + CLOCK_SLACK_SECONDS) throw new HttpError(422, "too_fast");
