	const today = serverDate(now);
	let key;
	let date = null;
	if (board === "daily") {
		date = q.get("date") ?? today;
		if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || ![0, 1].includes(daysBetween(date, today))) throw new HttpError(400, "bad_date");
		key = K.daily(date);
	} else if (board === "alltime" && !q.has("date")) key = K.alltime;
